def longestDiverseString(a: int, b: int, c: int) -> str:
    res = []
    counts = {'a': a, 'b': b, 'c': c}

    while True:
        # Sort characters by count descending
        sorted_chars = sorted(counts.keys(), key=lambda x: counts[x], reverse=True)

        best_char = None
        second_best_char = None

        if sorted_chars[0] == sorted_chars[1]:
            # If top two are equal, pick the one not same as last char if possible
            if len(res) > 0 and res[-1] == sorted_chars[0]:
                best_char = sorted_chars[1]
                second_best_char = sorted_chars[0]
            else:
                best_char = sorted_chars[0]
                second_best_char = sorted_chars[1]
        else:
            best_char = sorted_chars[0]
            second_best_char = sorted_chars[1]

        # Check if we can add best_char
        if counts[best_char] > 0:
            # Check if adding best_char would create 3 consecutive same chars
            if len(res) >= 2 and res[-1] == best_char and res[-2] == best_char:
                # Try second best
                if counts[second_best_char] > 0:
                    res.append(second_best_char)
                    counts[second_best_char] -= 1
                else:
                    # Cannot add anything valid
                    break
            else:
                res.append(best_char)
                counts[best_char] -= 1
        else:
            # Best char exhausted, try second best
            if counts[second_best_char] > 0:
                if len(res) >= 2 and res[-1] == second_best_char and res[-2] == second_best_char:
                    break
                res.append(second_best_char)
                counts[second_best_char] -= 1
            else:
                # Try third best
                third_best = sorted_chars[2]
                if counts[third_best] > 0:
                    if len(res) >= 2 and res[-1] == third_best and res[-2] == third_best:
                        break
                    res.append(third_best)
                    counts[third_best] -= 1
                else:
                    break

        # Check if all counts are zero
        if counts['a'] == 0 and counts['b'] == 0 and counts['c'] == 0:
            break

    return "".join(res)
